  function themePicker(){const rows=allPictures();return `<div class="av-theme-picker"><label for="av-theme">Tu mundo de imágenes</label><select id="av-theme" data-adventure-filter="theme"><option value="">Mezclar los ${THEMES.length} mundos · ${rows.length} imágenes</option>${THEMES.map(t=>`<option value="${esc(t.id)}" ${state.theme===t.id?'selected':''}>${esc(t.es)} · ${rows.filter(row=>row.theme===t.id).length} imágenes</option>`).join('')}</select><small>Este filtro se aplica al mercado y a las parejas.</small></div>`;}
